************************************************************************************/

scwin.vScrenID = "ULDSTF09306.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = "";
scwin.TR_JOB;
//scwin.VListBzTpCd = LIST_BZ_TP_CD_811; //PF 변경상장
scwin.VListBzTpCd = "811"; //PF 변경상장
scwin.MSG_50M_LOW = '신탁원본액 50억미만에 해당됩니다.';

scwin.BTN_MAP = {
    "save" : "btn_save",       // [저장]
    "modify" : "btn_update",      // [수정]
    "delete" : "btn_delete",     // [삭제]
    "guide" : "btn_dscl",   // [안내문]
};

scwin.onpageload = function() {
    scwin.init();
};

/* 
 * 화면 초기화
 */
scwin.init = function() {
    btn_RecvIsuDel.hide();

    var pData = $c.data.getParameter().pData; // 부모화면에서 넘어온 데이터
    console.log("pData");
    console.log(pData);

    if($c.util.isEmpty(pData)) {
        return;
    } else {
        scwin.vBzProcsNo = pData.clickBzProcsNo;
        scwin.vAcptNo = pData.vAcptNo;
        scwin.vIsurCd = pData.vIsurCd;
        scwin.vOpenTyp = pData.vOpenTyp;
        txb_ISU_CD.setValue(pData.isuCd);
        txb_ISU_NM.setValue(pData.isuNm);
    }


    if (scwin.vOpenTyp == "R") {
        scwin.search();
    } else if (scwin.vOpenTyp == "H") {
        scwin.search();
    } else if (scwin.vOpenTyp == "N") {
        scwin.search("N");
        scwin.fn_initItem();
    }
};

/* 
 * 데이터 조회
 */
scwin.search = async function(param){
    //초기화
    dma_isu.setEmptyValue();

    if(param == "N"){
        //신규버튼으로 진입시
        const sbmOptions = {
            id: "sbm_listhist",
            action: "/api/listing/lstproc/pf/chglisting/new",
            method: "get",
            target: "dma_isu=body",
            isProcessMsg: false
        };

        var result = await $c.sbm.executeDynamic(sbmOptions, {isuCd: txb_ISU_CD.getValue()});
        if(result.responseJSON.success){
            if (scwin.vOpenTyp == "N" || (scwin.vOpenTyp == "R" && scwin.vBzProcsNo== '')) {
                $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
            } else {
                $c.stf.setButtonSetWithDate(edt_LIST_DD, false, "grp_btnBox", scwin.BTN_MAP);
                $c.stf.setButtonSetWithDate2(dma_isu.get("disclsYn"));
            }
        }
    }else{
        const sbmOptions = {
            id: "sbm_listhist",
            action: "/api/listing/lstproc/pf/chglisting/select-one-hist",
            method: "get",
            target: "dma_isu=body",
            isProcessMsg: false
        };

        var result = await $c.sbm.executeDynamic(sbmOptions, {bzProcsNo: scwin.vBzProcsNo});
        if(result.responseJSON.success){
            if (scwin.vOpenTyp == "N" || (scwin.vOpenTyp == "R" && scwin.vBzProcsNo== '')) {
                $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);
            } else {
                $c.stf.setButtonSetWithDate(edt_LIST_DD, false, "grp_btnBox", scwin.BTN_MAP);
                $c.stf.setButtonSetWithDate2(dma_isu.get("disclsYn"));
            }
        }

    }


}

//버튼 ctrl
scwin.setbtn = function(param){
    if(param == "I"){
        btn_Dscl.setDisabled(true); //안내문
        btn_Update.setDisabled(true); //수정
        btn_Save.setDisabled(false); //저장
        btn_Delete.setDisabled(true); //삭제
    }else if(param == "U"){
        btn_Dscl.setDisabled(false); //안내문
        btn_Update.setDisabled(false); //수정
        btn_Save.setDisabled(true); //저장
        btn_Delete.setDisabled(false); //삭제
    }
}

/* 
 * 신규일 때 세팅
 */
scwin.fn_initItem = function() {
    if (scwin.vOpenTyp === "X") {
        $c.stf.setObjectValue(cmb_LIST_METHD_TP_CD, $c.lc.glb.LIST_METHD_TP_CD_4);//신규상장
    } else {
        $c.stf.setObjectValue(cmb_LIST_METHD_TP_CD, $c.lc.glb.LIST_METHD_TP_CD_3);//변경상장
    }
    $c.stf.setObjectValue(edt_TRST_DISTR_PAY_BAS_DD, $c.date.getServerDateTime().substring(0, 4) + "0101");

};

scwin.fn_calcuate = function() {
    try {
        if("" != edt_INCDEC_LIST_SHRS.getValue()){
            var vsum = parseInt($c.stf.getObjectValue(edt_BF_LIST_SHRS) == '' ? 0 : edt_BF_LIST_SHRS.getValue()) + parseInt($c.stf.getObjectValue(edt_INCDEC_LIST_SHRS));
            $c.stf.setObjectValue(edt_LIST_SHRS, vsum);
        }
    } catch (err) {
        $c.win.alert("[증권수 합산처리 중  오류]");
    }
};

// scwin.fn_50mcalcuate = function() {
//     if (($c.stf.getObjectValue(edt_LIST_SHRS) * dts_Isu.getCellData(1, "ISU_PRC")) < 5000000000) {
//         $c.win.alert(scwin.MSG_50M_LOW);
//     }
// };

/* 
 * 유효성 체크
 */
scwin.fn_CheckForm = async function() {
    var vCurDate = $c.date.getServerDateTime();

    if ("" == txb_ISU_CD.getValue()) {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }

    if ("" == edt_LIST_DD.getValue()) {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= edt_LIST_DD.getValue()) {
        await $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }

    if(!$c.date.checkCalendarFormat(edt_LIST_DD, "yyyyMMdd")){
        await $c.win.alert($c.data.getMessage("com_date_compare_0014"));//날짜 형식이 잘못 되었습니다. 확인 후 수정해 주세요.
        edt_LIST_DD.focus();
        return false;
    }

    if ("" == edt_BENFCERT_ESTBREPUR_DD.getValue()) {
        await $c.win.alert("[설정및환매일]을 입력하세요.");
        edt_BENFCERT_ESTBREPUR_DD.focus();
        return false;
    }

    if(!$c.date.checkCalendarFormat(edt_BENFCERT_ESTBREPUR_DD, "yyyyMMdd")){
        await $c.win.alert($c.data.getMessage("com_date_compare_0014"));//날짜 형식이 잘못 되었습니다. 확인 후 수정해 주세요.
        edt_BENFCERT_ESTBREPUR_DD.focus();
        return false;
    }

    if ("" == cmb_LIST_METHD_TP_CD.getValue()) {
        await $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_INCDEC_LIST_SHRS) == "") {
        $c.win.alert("[증감증권수]을 입력하세요.");
        edt_INCDEC_LIST_SHRS.focus();
        return false;
    }
    if (! await scwin.fn_checkNumber(edt_INCDEC_LIST_SHRS, '증감증권수')) return false;

    if ($c.stf.getObjectValue(edt_LIST_SHRS) == "") {
        await $c.win.alert("[변경후 상장증권수]을 입력하세요.");
        edt_LIST_SHRS.focus();
        return false;
    }
    if (! await scwin.fn_checkNumber(edt_LIST_SHRS, '변경후 상장증권수')) return false;

    if ($c.stf.getObjectValue(cmb_ISU_RSN_CONTN) == "") {
        await $c.win.alert("[변경사유]를 입력하세요.");
        cmb_ISU_RSN_CONTN.focus();
        return false;
    }

    if ($c.stf.getObjectValue(edt_TRST_DISTR_PAY_BAS_DD) == "") {
        await $c.win.alert("[분배지급기준일]을 입력하세요.");
        edt_TRST_DISTR_PAY_BAS_DD.focus();
        return false;
    }

    if(!$c.date.checkCalendarFormat(edt_TRST_DISTR_PAY_BAS_DD, "yyyyMMdd")){
        await $c.win.alert($c.data.getMessage("com_date_compare_0014"));//날짜 형식이 잘못 되었습니다. 확인 후 수정해 주세요.
        edt_TRST_DISTR_PAY_BAS_DD.focus();
        return false;
    }


    if ($c.stf.getObjectValue(txa_REMK).length > 500) {
        await $c.win.alert("[기타]항목이 입력사이즈를 초과하였씁니다.");
        txa_REMK.focus();
        return false;
    }

    return true;
};

scwin.fn_checkNumber = async function(obj, str) {
    if ($c.stf.getObjectValue(obj) == 0) {
        await $c.win.alert("[" + str + "]를 '" + $c.stf.getObjectValue(obj) + "'으로 입력하셨습니다. 확인 후 재입력바랍니다.");
        obj.focus();
        return false;
    }
    return true;
};

//저장
scwin.fn_save = async function() {
    scwin.TR_JOB = 'I';

    if (await scwin.fn_CheckForm()) {
        if (!await $c.lc.isProcess(scwin.TR_JOB)) return;

        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();
        console.log("getnewBz 결과: " + scwin.vBzProcsNo);

        if ($c.str.getByteLength(scwin.vBzProcsNo.toString()) != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dma_isu.set("bzProcsNo", scwin.vBzProcsNo)
            scwin.fn_trs($c.lc.glb.TRS_IDX_INSERT);
        }
    }
};

scwin.fn_update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.fn_CheckForm()) {
        if (!await $c.lc.isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs($c.lc.glb.TRS_IDX_UPDATE);
    }
};

scwin.fn_delete = async function() {
    scwin.TR_JOB = 'D';
    //TODO 확인필요 
    //if (!fn_check_delete_discls_procsstat(dts_DELETE, dts_Isu.getCellData(1, "BZ_PROCS_NO"))) return;

    if (! await $c.lc.isProcess(scwin.TR_JOB)) return;

    scwin.fn_trs($c.lc.glb.TRS_IDX_DELETE);
};

//API호출
scwin.fn_trs = async function(trsIdx) {
    dma_input.setEmptyValue();
    dma_input.setJSON(dma_isu.getJSON());

    dma_input.set("acptNo", scwin.vAcptNo);
    dma_input.set("byacptnoSeq", "1");
    dma_input.set("bzProcsNo", scwin.vBzProcsNo);
    dma_input.set("count", 1);
    dma_input.set("listBzTpCd", scwin.VListBzTpCd);
    dma_input.set("isurCd", scwin.vIsurCd);
    dma_input.set("isuCd", txb_ISU_CD.getValue());

    if (scwin.TR_JOB == 'I') {
        //저장
        svcId = "insert";
    } else if (scwin.TR_JOB == 'U') {
        //수정
        svcId = "update";
    } else if (scwin.TR_JOB == 'D') {
        //삭제
        svcId = "delete";
    }

    const sbmOptions = {
        id: "sbm_pf",
        action: "/api/listing/lstproc/pf/chglisting/" + svcId,
        mediatype: "application/json",
        method: "post",
        //ref: 'data:json,[{"id":"dma_in","key":"delistingEtfSaveRequestDto"}]', 
        ref: "dma_input", 
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);

    if (res.responseJSON.success) {
        scwin.fn_parentRefresh();

        $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);

        if(scwin.TR_JOB == 'I'){
            await $c.win.alert($c.data.getMessage("com_complete_0096", "저장"));
        }else if(scwin.TR_JOB == 'U'){
            await $c.win.alert($c.data.getMessage("com_complete_0096", "수정"));
        }else if(scwin.TR_JOB == 'D'){
            await $c.win.alert($c.data.getMessage("com_complete_0096", "삭제"));
            $c.win.closePopup();
        }

        //재조회
	    scwin.search();

    }
};


//신청종목삭제
scwin.fn_RecvtIsuDel = async function() {
    //ASIS 소스상 show 해주는 부분이 없음
    if (scwin.vAcptNo == "") {
        $c.win.alert('발행예정내역에서 대상종목을 선택하세요');
        return;
    }

    scwin.TR_JOB = 'D';
    if (!await $c.win.confirm($c.stf.getMessageParam('MSG-A006', "신청종목삭제"))) return;

    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();
    console.log("getnewBz 결과: " + scwin.vBzProcsNo);

    if ($c.str.getByteLength(scwin.vBzProcsNo.toString()) != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dma_input.setEmptyValue();
        dma_input.setJSON(dma_isu.getJSON());
        dma_input.set("acptNo", scwin.vAcptNo);
        dma_input.set("byacptnoSeq", "1");
        dma_input.set("bzProcsNo", scwin.vBzProcsNo);
        dma_input.set("count", 1);
        dma_input.set("listBzTpCd", scwin.VListBzTpCd);
        dma_input.set("isurCd", scwin.vIsurCd);
        dma_input.set("isuCd", txb_ISU_CD.getValue());

        const sbmOptions = {
            id: "sbm_pfrecv",
            action: "/api/listing/lstproc/pf/chglisting/delete-isu",
            mediatype: "application/json",
            method: "post",
            //ref: 'data:json,[{"id":"dma_in","key":"delistingEtfSaveRequestDto"}]', 
            ref: "dma_input", 
            isProcessMsg : false
        };

        const res = await $c.sbm.executeDynamic(sbmOptions);

        if (res.responseJSON.success) {
            await $c.win.alert($c.data.getMessage("com_complete_0096", "삭제"));
        }
    }
};



